/**
 * Searches Mathematics textbook chunks (Chapters 1-9: Limits, Derivatives, Primitives, Integrals, Curves, Complex, Conics, DiffEq, Probability, Vectors in Space - 100% of Grade 12 Math Summary Textbook) for matches against a student query.
 * Returns up to maxResults retrieved chunks formatted for KruAI's system prompt.
 */
export function searchMathTextbook(
  query: string,
  maxResults = 2
): RetrievedChunk[] {
  return searchSections(
    query,
    ALL_MATH_SECTIONS,
    "សៀវភៅសង្ខេបគណិតវិទ្យាថ្នាក់ទី 12 (ក្រសួងអប់រំ)",
    maxResults
  );
}

